"use client"

import { createContext, useContext, useState, useCallback, useEffect, type ReactNode } from "react"

const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL || ""

export interface UserProfile {
  id: number
  gender: string | null
  maritalStatus: string | null
  position: string | null
  dateOfBirth: string | null
  profileImage: string | null
}

export interface User {
  id: number
  name: string
  email: string
  phone: string
  role: "admin" | "cfo" | "accountant" | "user" | "viewer"
  createdAt: string
  updatedAt: string
  deletedAt: string | null
  profile: UserProfile | null
}

interface AuthTokens {
  accessToken: string
  refreshToken: string
}

interface LoginResponse {
  user: User
  accessToken: string
  refreshToken: string
}

interface AuthContextType {
  user: User | null
  isAuthenticated: boolean
  isLoading: boolean
  tokens: AuthTokens | null
  login: (email: string, password: string) => Promise<boolean>
  logout: () => void
}

const AuthContext = createContext<AuthContextType | undefined>(undefined)

// Storage keys
const USER_STORAGE_KEY = "irebe_user"
const TOKENS_STORAGE_KEY = "irebe_tokens"

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null)
  const [tokens, setTokens] = useState<AuthTokens | null>(null)
  const [isLoading, setIsLoading] = useState(false)

  // Load user from storage on mount
  useEffect(() => {
    const storedUser = localStorage.getItem(USER_STORAGE_KEY)
    const storedTokens = localStorage.getItem(TOKENS_STORAGE_KEY)
    
    if (storedUser && storedTokens) {
      try {
        setUser(JSON.parse(storedUser))
        setTokens(JSON.parse(storedTokens))
      } catch {
        localStorage.removeItem(USER_STORAGE_KEY)
        localStorage.removeItem(TOKENS_STORAGE_KEY)
      }
    }
  }, [])

  const login = useCallback(async (email: string, password: string): Promise<boolean> => {
    setIsLoading(true)

    try {
      const response = await fetch(`${API_BASE_URL}auth/login`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ email, password }),
      })

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        console.error("Login failed:", errorData)
        setIsLoading(false)
        return false
      }

      const data: LoginResponse = await response.json()

      // Store user and tokens
      setUser(data.user)
      setTokens({
        accessToken: data.accessToken,
        refreshToken: data.refreshToken,
      })

      // Persist to localStorage
      localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(data.user))
      localStorage.setItem(TOKENS_STORAGE_KEY, JSON.stringify({
        accessToken: data.accessToken,
        refreshToken: data.refreshToken,
      }))

      setIsLoading(false)
      return true
    } catch (error) {
      console.error("Login error:", error)
      setIsLoading(false)
      return false
    }
  }, [])

  const logout = useCallback(() => {
    setUser(null)
    setTokens(null)
    localStorage.removeItem(USER_STORAGE_KEY)
    localStorage.removeItem(TOKENS_STORAGE_KEY)
  }, [])

  return (
    <AuthContext.Provider
      value={{
        user,
        isAuthenticated: !!user,
        isLoading,
        tokens,
        login,
        logout,
      }}
    >
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  const context = useContext(AuthContext)
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider")
  }
  return context
}
