export async function fetchCompanyDetail(companyId: string) {
  await delay(300)
  const company = mockCompanies.find((c) => c.id === parseInt(companyId))
  const transactions = companyTransactions[companyId.toLowerCase()] || []
  
  return {
    ...company,
    openingBalance: company?.cashBalance || "RWF 0",
    closingBalance: company?.cashBalance || "RWF 0",
    netChange: company?.todayProfit?.replace("+", "") || "RWF 0",
    revenueTransactions: transactions.filter((t) => t.type === "income").length,
    expenseTransactions: transactions.filter((t) => t.type === "expense").length,
    transactions,
  }
}

